xpath.script:
{
    const os = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    const known = document.cookie.match(/(?:^|; )eg_os_scheme=(dark|light)/);
    if (os !== (known ? known[1] : "light")) {
        document.cookie = "eg_os_scheme=" + os + "; path=/; max-age=31536000; SameSite=Lax";
        // Reload only if the cookie stuck, otherwise it would loop.
        if (document.cookie.includes("eg_os_scheme=" + os)) {
            window.location.reload();
        }
    }
}
